CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_premium_proof
COMMENT 'The premium reconciliation, by line of business and currency: written premium equals earned to date plus unearned (UPR). The residual must be zero - this is the proof that the earning engine conserves premium, shown as one number a controller can trust. Derived from the premium_earning view. Grain: One row per line of business per currency.'
AS
SELECT
  line_of_business_code,
  currency_code,
  CAST(SUM(written_premium) AS DECIMAL(18,2)) AS written_premium,
  CAST(SUM(earned_premium) AS DECIMAL(18,2)) AS earned_premium,
  CAST(SUM(unearned_premium) AS DECIMAL(18,2)) AS unearned_premium,
  CAST(SUM(written_premium) - SUM(earned_premium) - SUM(unearned_premium)
    AS DECIMAL(18,2)) AS residual
FROM lr_serverless_aws_us_catalog.bricksurance_semantics.premium_earning
GROUP BY line_of_business_code, currency_code;
